def set_port_size_and_quantity(apps, schema_editor):
    """
    forward migration that sets the port size and quanity and lag
    based on speed, before the speed field is removed
    """

    # valid port sizes are defined in settings.PORT_SIZES
    # e.g., [1, 10, 100]

    # so take speed / closest port size, and set port size to that
    # if speed is not a multiple of a port size, set port size to the next highest port size
    # set port quantity to speed / port size
    # if multiple set lag to True
    # if speed is 0 or none, set port size to 1 and port quantity to 1

    # speed is stored in Mb
    # port size choices are in Gb

    InternetExchangeMember = apps.get_model("django_ixctl", "InternetExchangeMember")

    max_port_quantity = settings.PORT_LIMIT_MAX

    # port sizes sorted in descending order
    port_sizes = sorted(settings.PORT_SIZES, reverse=True)

    for member in InternetExchangeMember.handleref.all():
        if member.speed is None or member.speed == 0:
            member.port_size = 1
            member.port_quantity = 1
        else:
            port_size = min(port_sizes)
            for size in port_sizes:
                if (member.speed / 1000) < size * max_port_quantity:
                    port_size = size
            member.port_size = port_size
            member.port_quantity = member.speed / (port_size * 1000)

            # port quantity is an integer, so round up if necessary
            if member.port_quantity % 1 != 0:
                member.port_quantity = int(member.port_quantity) + 1
            else:
                member.port_quantity = int(member.port_quantity)

            member.lag = member.port_quantity > 1

        member.save()


